globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-27 13:00:11 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"米、スペースXに衛星100万基の配備承認　宇宙にAIデータセンター構築へ","url":"https://www.cnn.co.jp/usa/35255487.html","source":"Hatena","published_at":"2026-11-27 10:03","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"米FCC、スペースXの衛星100万基配備を承認し宇宙AIデータセンターへ","summary":"米連邦通信委員会（FCC）が、スペースXによる100万基の衛星コンステレーション「スターマインド」の配備を承認。宇宙空間にAIデータセンターを構築し、増大するAI計算需要に対応する狙いです。\n\n太陽エネルギーを直接活用することで、地上データセンターと比較してコストとエネルギー効率を飛躍的に高める構想。実現すれば、AIインフラのあり方を根本から変える可能性があります。","importance":10},{"title":"Androidアプリ開発者はまもなく自身の住所を公開しなければならなくなる","url":"https://gigazine.net/news/20261127-android-app-developers-have-to-share-address-publicly/","source":"Hatena","published_at":"2026-11-27 11:28","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Androidアプリ開発者、2027年から住所公開が必須に","summary":"GoogleがEUのデジタルサービス法（DSA）に対応するため、2027年2月以降、Androidアプリ開発者に対して事業者かどうかの申告を義務付けると発表。事業者に該当する場合、住所や電話番号が公開されることになります。\n\n私書箱の利用が認められないため、オフィスを持たない個人開発者は自宅住所の公開を迫られることになり、プライバシー保護の観点から大きな懸念が広がっています。","importance":9},{"title":"航空会社Peach、「KARTE」から最大約944万件の顧客情報漏えい　契約終了後も削除されず残存","url":"https://www.itmedia.co.jp/news/article/2611/27/2000003509/","source":"Hatena","published_at":"2026-11-27 10:21","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Peachの顧客情報約944万件が漏えい、契約終了後のデータ残存が原因","summary":"格安航空会社Peach Aviationが、マーケティングサービス「KARTE」への不正アクセスにより、最大約944万件の顧客情報が漏えいしたと発表。契約終了後に削除されるべきデータが、管理不備により残存していたことが原因です。\n\n漏えいデータには氏名や住所などが含まれますが、カード情報やパスポート情報は含まれていません。Peachはプレイドに対し、完全消去と証明書の提出を求めています。","importance":9},{"title":"◯✗ゲーム++：FIFO ◯✗ゲームにおいて先手が 13 手で勝つことの証明","url":"https://zenn.dev/akitenkrad/articles/wq6lzq7xa036ff","source":"Zenn","published_at":"2026-11-27 08:00","genre":"other","genre_label":"総合・その他IT","headline":"FIFO方式の◯✗ゲームにおいて先手が13手で勝利することを数学的に証明","summary":"FIFO（先入れ先出し）ルールを適用した◯✗ゲームにおいて、k=3の条件下で先手が13手で勝利することを全数探索に頼らず証明した。このゲームでは古典的な二重リーチは発生せず、相手の古い手が消える特性を利用した「トラップ」が勝敗を分ける。\n\n証明は、先手が13手目までに勝てることと、13手未満では勝てないことの両面から範囲を絞り込む手法を採用。6つの補題を組み合わせることで、ゲームの決着がちょうど13手になることを理論的に導き出した。","importance":4},{"title":"Kong×MuleSoft の外部連携を12項目で固め、再検証で落とし穴を3つ見つけた話","url":"https://zenn.dev/kensudo1203/articles/edbd45f1bf44d1","source":"Zenn","published_at":"2026-11-27 11:06","genre":"web","genre_label":"Web開発・言語","headline":"APIゲートウェイ連携を12項目で固め、再検証で落とし穴を特定","summary":"KongとMuleSoftを組み合わせた銀行システムサンプルにおいて、外部連携のセキュリティを強化した事例。APIキー認証からOAuth 2.0への移行や、署名付きトークンの導入、ネットワーク分離などを実施しました。\n\n実装後に改めて検証を行った結果、テストコードの誤りや設計上の見落としを3つ発見。一度の設計で満足せず、多角的な再検証を行うことの重要性を説いています。","importance":7},{"title":"X、「ペアレンタルコントロール」を導入　メッセージ内容は見られず","url":"https://www.itmedia.co.jp/news/article/2611/27/2000003506/","source":"Hatena","published_at":"2026-11-27 07:33","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Xが10代向けペアレンタルコントロール導入、DM内容の閲覧は不可","summary":"米Xは13〜17歳のユーザーを対象としたペアレンタルコントロール機能を導入した。保護者は利用時間の上限設定や、フォロー・DM相手の管理、センシティブなコンテンツの制限が可能となる。\n\nアカウントの所有権は子ども本人にあり、保護者は設定変更の履歴を確認できるが、DMの内容や閲覧履歴までは見られない仕様。連携には双方の同意が必要であり、子どものプライバシーと安全保護のバランスを考慮した設計となっている。","importance":6},{"title":"禁止しても止まらないClaudeの「欲」を飼いならしてみる","url":"https://zenn.dev/rescuenow/articles/9d1e89a941f4f1","source":"Zenn","published_at":"2026-11-27 11:47","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claudeの「余計な挙動」を抑制するプロンプトの最適解を検証","summary":"Claudeにコード生成を依頼する際、指示外の挙動を勝手に足してしまう「欲」をどう制御するかを検証した実験。禁止命令やドキュメント化、Issue起票などの手法を試しましたが、いずれも根本的な解決には至りませんでした。\n\n最終的に「xfail（期待される失敗）」をテストコードとして書かせる手法が、本体コードへの余計な追加をゼロにする最も有効な手段であることを発見。AIの「正しく動かしたい」という意図を、テストという形で昇華させるアプローチが示されました。","importance":8},{"title":"ニュース一覧 | ちいかわクリスマスマーケット","url":"https://contents-abema.com/chiikawa-christmas-market/news/","source":"Hatena","published_at":"2026-11-26 22:52","genre":"other","genre_label":"総合・その他IT","headline":"「ちいかわクリスマスマーケット」グッズ完売による受注販売への切り替え","summary":"「ちいかわクリスマスマーケット」において、限定グッズが即日完売したことを受け、運営が受注販売への切り替えを発表した。チケット保有者と一般客の2段階で受付を行い、希望者全員への提供を目指す。\n\nイベント運営における在庫管理の不備に対する謝罪と、チケットの払い戻し対応も併せて実施される。人気コンテンツのイベント運営において、需要予測とサーバー負荷対策の重要性が改めて示された事例である。","importance":3},{"title":"マイナー試験の学習教材がなければ、自分専用学習アプリをつくるのがあり","url":"https://zenn.dev/tm35/articles/ead959b46bfebb","source":"Zenn","published_at":"2026-11-26 20:03","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"過去問をAIでデジタル化し自分専用の学習アプリを個人開発","summary":"学習教材が少ないマイナー資格の対策として、過去問をAIでテキスト化し、Cloudflare WorkersとD1を用いた自分専用の学習アプリを開発した事例。スマホで撮影した問題をAIで構造化し、解説を補完させることで、スキマ時間に効率よく学習できる環境を構築した。\n\n単なる問題演習だけでなく、回答データをClaude Codeで分析して苦手分野を特定し、対策問題を出題させるという高度な学習ループを実現。個人開発だからこそ可能なデータ活用と、AIを家庭教師のように使い倒すアプローチは、効率的な資格取得を目指すエンジニアにとって非常に示唆に富む。","importance":7},{"title":"gh-ostで2,500万行のテーブル変更をクエリ待ち1.31秒で通した話：Aurora MySQLへの導入と本番クローンでの検証 - Findy Tech Blog","url":"https://tech.findy.co.jp/entry/2026/11/27/070000","source":"Hatena","published_at":"2026-11-27 09:33","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"gh-ost導入で巨大テーブルのオンラインDDLを安全に実行","summary":"数千万〜数億行のテーブルを持つAurora MySQL環境において、GitHub製OSS「gh-ost」を導入し、安全なオンラインDDLを実現した事例。従来の手法では負荷制御が困難だった大規模テーブルのNOT NULL化を、クエリ待ち時間1.31秒で完了させました。\n\n本番クローンを用いた検証手順や、運用に乗せるための仕組み作りを詳細に解説。大規模DB運用における安全なマイグレーション手法として参考になります。","importance":8},{"title":"SWCベースのi18next-cliへ移行して、翻訳キーの抽出時間を約5分の1に高速化した話","url":"https://zenn.dev/aldagram_tech/articles/5b09a02dd4c383","source":"Zenn","published_at":"2026-11-27 12:00","genre":"web","genre_label":"Web開発・言語","headline":"i18next-cliへの移行で翻訳キー抽出時間を5分の1に短縮","summary":"アルダグラム社が、Webアプリの多言語対応における翻訳キー抽出処理をBabelベースからi18next-cliへ移行した事例。従来のBabelを用いた手法ではトランスパイルが毎回走り、約100秒を要していましたが、専用ツールへの置き換えにより約19秒まで短縮しました。\n\n移行にあたっては、キーのネスト構造や複数形の設定を既存の辞書形式と整合させるための調整を実施。CIでのチェック速度も向上し、開発効率の改善に成功しています。","importance":6},{"title":"人の承認はどこまで必要か：Claude Code チームに学ぶ「人の承認」と「自動承認」の境目","url":"https://zenn.dev/khayashida/articles/claude-code-team-review","source":"Zenn","published_at":"2026-11-26 12:47","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Claude Codeチームに学ぶ「人の承認」と「自動承認」の境界線","summary":"AnthropicのClaude Codeチームの事例を基に、AIによるコード生成が増える中で「人の承認」と「自動承認」の境目をどう引くかを解説しています。変更のリスクに応じて承認プロセスを段階化し、revert率やincident率をガードレールとして品質を維持する手法が紹介されています。\n\nPR前の検証手段の提供や、REVIEW.mdによるレビュー基準の明文化など、AIレビューアーを最大限活用するための仕組み作りが重要です。出荷した変更の責任は人が持つという原則のもと、レビューの手間を減らしつつ品質を担保する組織運営の指針となります。","importance":9},{"title":"評価基準と現場の慣習が食い違うとき、注記を足すとLLM判定器はどう変わるか ― 999件と未見の300件で確かめた","url":"https://zenn.dev/quent/articles/0a29761c6d2cb9","source":"Zenn","published_at":"2026-11-27 11:33","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"LLM判定器の評価基準と現場慣習の食い違いを注記で解消","summary":"LLMによる会話品質の採点において、評価基準と日本の地域慣習（名字＋様など）が食い違う問題を、注記の追加によって解決した検証記事。999件のデータと追加の300件を用いて、4つのClaudeモデルで精度を測定しました。\n\n注記を3行加えるだけで、誤減点率を劇的に改善しつつ、本来の違反検出精度を維持できることを実証。LLM判定器の運用において、基準を書き換えるのではなく注記で補完する手法の有効性が示されました。","importance":8},{"title":"【やじうまミニレビュー】 工具のマキタバッテリがPCの電源に!? 最大100Wの純正アダプタを使ってみた","url":"https://pc.watch.impress.co.jp/docs/column/yajiuma-mini-review/2159706.html","source":"Hatena","published_at":"2026-11-27 07:47","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"マキタの電動工具用バッテリをPC電源に変換するアダプタ「ADP15」の実力","summary":"マキタの電動工具用バッテリをモバイル電源として活用できるアダプタ「ADP15」のレビュー。USB Type-Cポートから最大100W（PPS対応）の給電が可能で、ノートPCの充電にも余裕で対応できる性能を持つ。\n\n災害時の非常用電源として非常に有用だが、バッテリ自体の充電機能はない点に注意が必要。電動工具のバッテリを複数所有しているユーザーにとっては、ポータブル電源の代わりとなる強力なバックアップ手段となる。","importance":5},{"title":"iostatは正常なのにp99だけ遅い原因はcgroupのIOPS上限","url":"https://zenn.dev/shinagawa_web/articles/io-max-hidden-from-iostat","source":"Zenn","published_at":"2026-11-27 08:01","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"iostat正常でもp99が遅い原因はcgroupのIOPS上限設定","summary":"アプリケーションのp99レイテンシだけが跳ね上がる現象の原因として、cgroupのIOPS上限設定を解説。iostatのr_awaitや%utilが低い場合でも、カーネル内のblk-throttleによって読み込みが一時停止されている可能性があることを指摘しました。\n\nカーネルが100ms単位の区切りでIOPSを制限する仕組みを詳細に分析。上限に張り付いている際に発生するレイテンシのスパイクを理解し、適切にチューニングするための技術的知見を提供しています。","importance":8},{"title":"GitHub - datadog-labs/ephyra: A property-based testing library for the LLM era","url":"https://github.com/datadog-labs/ephyra","source":"Hatena","published_at":"2026-11-27 06:56","genre":"web","genre_label":"Web開発・言語","headline":"Datadogが開発したLLM時代のプロパティベーステストライブラリ「Ephyra」","summary":"Datadog Systems Researchが開発した、エージェントによるプロパティベーステストのための新ライブラリ「Ephyra」。従来のファジングと異なり、LLMを活用してテストケース生成器を最適化する帰納的なアプローチを採用している。\n\nSQLiteやPostgreSQLなど著名なプロジェクトで既に70以上のバグを発見する実績を持つ。コーディングエージェントにテストを書かせることを前提に設計されており、LLM時代のソフトウェア品質保証における新たな手法として注目される。","importance":7},{"title":"サイバー攻撃深刻化、「ひとり情シス」は危機管理上リスク…デジタル人材不足はＤＸの障壁に","url":"https://www.yomiuri.co.jp/economy/20261127-GYT1T00002/","source":"Hatena","published_at":"2026-11-27 05:08","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"「ひとり情シス」の危機管理リスクとデジタル人材不足の深刻化","summary":"自治体や企業におけるデジタル人材不足がDXの大きな障壁となっている。特に専任担当者が不在の「ひとり情シス」状態の自治体は全国で1割を超え、サイバー攻撃への対応能力が懸念されている。\n\n人材不足を補うため、ローソンなどの企業では非IT部門の社員を「市民開発者」として育成する動きが加速している。政府もデジタル人材育成を推進しているが、AI時代に対応した高度なセキュリティや業務効率化を担える人材の確保が急務である。","importance":7},{"title":"さくらインターネット、AIを月額固定料金で提供する「シンプルAI」発表、システムへの組み込み用途を想定","url":"https://www.publickey1.jp/blog/26/aiai_1.html","source":"Hatena","published_at":"2026-11-27 08:09","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"さくらインターネット、システム組み込み向け月額固定AI「シンプルAI」発表","summary":"さくらインターネットが、月額固定料金で利用可能なAIサービス「シンプルAI」を発表。従量課金制の「さくらのAI Engine」とは異なり、システム組み込み用途での安定性を重視しています。\n\nAIモデルの変更による応答の変化を抑え、長期的に安定した運用を可能にすることを目指しており、ISMAP登録申請や国産LLMの提供も視野に入れています。","importance":8},{"title":"自作VMのボットが戦う、Raspberry Pi Zero 2 Wのペイント合戦専用機を作りました","url":"https://zenn.dev/pcfan/articles/a5455f166e02c3","source":"Zenn","published_at":"2026-11-26 13:52","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Raspberry Pi Zero 2 Wで動く自作VMペイント合戦機の開発","summary":"Raspberry Pi Zero 2 Wを活用し、自作の仮想マシン（VM）上でボット同士が盤面を塗り合う「ペイント合戦」専用機を構築した事例です。GUI環境を排除し、C言語で実装したゲームホストとVMを動かすことで、限られたリソースでも効率的にボット対戦を実現しています。\n\nボットの応答をタイムアウトやエラーを含めて管理する仕組みを導入し、観戦用のモニター表示まで作り込んでいます。ハードウェアの制約を逆手に取り、プログラミングの学習と遊びを融合させた個人開発の好例です。","importance":5},{"title":"AI に頼らず素手で挑む！カミナシ社内セキュリティ競技会『ごーとんカップ 2026』 - カミナシ エンジニアブログ","url":"https://kaminashi-developer.hatenablog.jp/entry/2026/11/27/123000","source":"Hatena","published_at":"2026-11-27 12:54","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AI禁止で基礎体力を問う！カミナシ社内セキュリティ競技会開催","summary":"カミナシが社内エンジニア向けに開催したセキュリティ競技会「ごーとんカップ 2026」のレポート。今回はAIの利用を禁止し、エンジニアが自身の基礎的なセキュリティスキルを再確認する場として企画されました。\n\nGitHub Actionsのシークレット漏洩やWAFログへのプロンプトインジェクションなど、実務に即した23問を出題。AIに頼り切った開発環境において、脆弱な実装を見抜くための「基礎体力」の重要性を再認識させるイベントとなりました。","importance":7},{"title":"デジタル庁デザインシステムをどう使うか：導入先に合わせた「ローカルデザインシステム」を作る｜デジタル庁ニュース","url":"https://digital-agency-news.digital.go.jp/articles/2026-11-26","source":"Hatena","published_at":"2026-11-26 19:02","genre":"web","genre_label":"Web開発・言語","headline":"デジタル庁デザインシステムを導入先に適応させるローカル化手法","summary":"デジタル庁が提供する「デジタル庁デザインシステム」を、各プロジェクトのブランドに合わせて再定義する「ローカルデザインシステム」の作成手法を解説。同システムは特定のブランドを持たない「プラットフォーム型」であり、そのまま使うのではなくデザイントークンを編集して適用することが推奨されている。\n\nカラー、タイポグラフィ、余白などの視覚要素を導入先の方針で上書きすることで、アクセシビリティを確保しつつ独自のトーン＆マナーを実現できる。行政システムのみならず、民間事業者も無料で利用可能なため、一貫性のあるUI設計を目指す開発者にとって重要なリソースとなる。","importance":6},{"title":"Agentforce エージェントからユーザー単位の認証で外部 MCP サーバーに接続する","url":"https://zenn.dev/hrendoh/articles/agentforce-mcp-per-user-auth","source":"Zenn","published_at":"2026-11-26 20:22","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Agentforceで外部MCPサーバーへのユーザー単位認証を実装","summary":"SalesforceのAgentforceにおいて、外部MCPサーバー（Asana等）への接続を「全ユーザー共有」から「ユーザー単位の認証」へ切り替える手順を解説。Winter '27でGAとなった本機能により、エージェントが実行する操作の作成者を、指示を出した本人に紐付けることが可能となった。\n\nOAuth 2.0のブラウザフローを活用し、共有サービスアカウントを廃止することで、監査証跡の明確化とセキュリティ向上が実現する。指定ログイン情報や外部ログイン情報の設定変更、権限セットの割り当てなど、実務で必要な設定フローを具体的に示しており、エンタープライズ環境でのエージェント運用に不可欠な知見である。","importance":7},{"title":"Skills over MCP、めっちゃよさそう | ashunar0","url":"https://ashunar0.dev/posts/skills-over-mcp/","source":"Hatena","published_at":"2026-11-27 07:15","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ClaudeのMCPに「Skills over MCP」登場、ツール操作の習熟を支援","summary":"AnthropicがMCP（Model Context Protocol）のアップデートを発表し、サーバーがツールだけでなく「スキル（操作手順）」も提供可能になった。これにより、Claudeは外部サービスを操作するだけでなく、最適な手順を理解して実行できるようになる。\n\nスキルはサーバー側で更新されるため、常に最新のマニュアルが適用される点が大きなメリット。ShopifyやHubSpotなどの複雑な業務フローを伴うツールにおいて、AIの活用効率を劇的に向上させる重要なアップデートである。","importance":8},{"title":"息子が父親のSwitchを勝手に持ち出し、公園で紛失して帰ってきた→「みまもりアプリ」に暗証番号入力ミスの通知が…息子への対応は？取り戻す方法は？","url":"https://togetter.com/li/2775400","source":"Hatena","published_at":"2026-11-27 04:52","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"子供がSwitchを紛失、親が直面する「みまもりアプリ」と責任のあり方","summary":"子供が親の所有するNintendo Switchを無断で持ち出し、公園で紛失した事例。みまもりアプリの通知から第三者による操作の形跡が確認され、盗難の可能性が浮上している。\n\n親はゲーム機そのものよりも、子供の信頼を裏切る行為への対応に苦慮している。紛失時の対応として警察への届け出やシリアルナンバーの確認、アカウントの保護などが議論されており、現代の家庭におけるデジタル機器の管理と子供のしつけの難しさが浮き彫りとなった。","importance":3},{"title":"止められないDBをAWS DMSで移行してハマったこと（RDS for Oracle）","url":"https://zenn.dev/kiri0728/articles/c8d5f349b047dd","source":"Zenn","published_at":"2026-11-27 11:37","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWS DMSによるRDS for Oracle移行で学んだハマりどころ","summary":"RDS for OracleをAWS DMSで移行した際のトラブルシューティング事例。フルロード後のCDC（差分同期）が機能しない問題や、接続テストでの名前解決エラーに直面しました。\n\n原因はサプリメンタルロギングの設定漏れやホスト名のタイプミスでした。今後は移行前のチェックリスト化やストレージ監視、接続先入力の自動化など、属人的な対応に頼らない仕組み作りが重要であると結論付けています。","importance":7},{"title":"Leanによる定理証明と実行時検証の実装例 〜バッテリーの充電制御〜","url":"https://zenn.dev/quetta_kazunoko/articles/battery-safety-lean","source":"Zenn","published_at":"2026-11-26 18:09","genre":"web","genre_label":"Web開発・言語","headline":"Leanを用いたバッテリー制御の形式検証と定理証明の実装例","summary":"バッテリーの充電制御を題材に、Leanを用いた「定理証明」と「実行時検証」という二つの形式手法の実装例を紹介しています。定理証明では、モデルが安全であるという命題を数学的に証明し、実行時検証では、プログラム実行時に条件を満たすかを判定するアルゴリズムを構築します。\n\nポイントは、安全性仕様（IsSafe）と制御器の要求仕様（ControllerSafe）を分離して定義することで、仕様変更への柔軟性を高めている点です。定理証明はモデルの論理的な正しさを保証しますが、実機環境との乖離を埋めるには実行時検証との組み合わせが重要であると示唆しています。","importance":6},{"title":"アプリケーションを作る時代から、アプリケーションを作る仕組みを育てる時代へ","url":"https://zenn.dev/vbaman/articles/455770696726af","source":"Zenn","published_at":"2026-11-26 18:29","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"個人開発の資産化：AI時代を見据えた「仕組み」を育てる開発へ","summary":"Excel VBAからGodot Engineでのエンジン開発へとシフトする中で、著者は「個別のアプリを作る技術」だけでなく「アプリを生み出す仕組みそのもの」を資産として育てる重要性を説いています。便利なツールを作るだけでは無償の労力消費になりがちですが、再利用可能なエンジンやデータ構造を整理することで、将来的なAIエージェントによる自動開発にも対応可能な基盤を構築できると主張しています。\n\n結論として、単発の成果物で終わらせず、人間が作ってもAIが作ってもすぐに動かして確認できる環境を整えることが、個人開発者にとっての生存戦略になると述べています。仕組みを作り込みすぎて開発が止まることを避けつつ、将来のAI活用を見据えた設計思想を持つことの重要性が強調されています。","importance":7},{"title":"Evolution Strategies at Scale: LLM Fine-Tuning Beyond Reinforcement Learning","url":"https://arxiv.org/abs/2509.24372","source":"Hatena","published_at":"2026-11-27 06:51","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"進化戦略（ES）を用いたLLMのフルパラメータファインチューニング手法","summary":"LLMのファインチューニングにおいて、強化学習（RL）に代わる手法として進化戦略（ES）の有効性を実証した論文。従来、ESは大規模モデルへの適用が困難とされていたが、本研究では数十億パラメータ規模での成功を収めた。\n\nESはバックプロパゲーションを必要とせず、報酬ハッキングへの耐性や学習の安定性に優れる。強化学習に依存しない新たな学習パラダイムとして、LLMのポストトレーニングにおける重要な選択肢となる可能性がある。","importance":9},{"title":"さくらのクラウド、新ネットワーク基盤、新データベースサービスなど投入。東京リージョン第三ゾーン新設も発表","url":"https://www.publickey1.jp/blog/26/post_310.html","source":"Hatena","published_at":"2026-11-27 08:04","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"さくらのクラウドが新ネットワーク基盤と新DBサービスを発表","summary":"さくらインターネットが大規模イベントにて、さくらのクラウドに関する新機能を多数発表。東京リージョンへの第三ゾーン新設に加え、論理ネットワークを抽象化する「ネットワークスイート」や、管理機能を統合した「データベーススイート」を投入しました。\n\n運用負荷の軽減とクラウドネイティブな設計を支援する機能強化により、エンタープライズ利用をさらに加速させる狙いです。","importance":7},{"title":"Aniwaffle | Expressive, lovable AI voices for your characters","url":"https://aniwaffle.com/","source":"Hatena","published_at":"2026-11-26 20:26","genre":"web","genre_label":"Web開発・言語","headline":"Expressive, playful TTS for real-time conversations that bring your…","summary":"Expressive, playful TTS for real-time conversations that bring your characters to life.Studio and API access are invite-only for now.\n\nListen to the samples below, or request an invitation to try it yourself.Hear expressive English and Japanese AI voice samples for companions, games and characters.\n\nAttractive voices Meet the personalities behind the voices.","importance":5},{"title":"個人の目標設定に悩んでいたら、アジャイルが言葉を定義し直すきっかけをくれた話","url":"https://zenn.dev/yoshipon_tech/articles/a0e13c3dbd2f7d","source":"Zenn","published_at":"2026-11-26 14:35","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"アジャイルの定義を再考し、個人の目標設定を仕組み化する","summary":"個人の目標設定が続かない悩みを、アジャイルの思考法を用いて解決する試みです。目標が「手段の目的化」に陥っていることに気づき、アジャイル宣言やスクラムガイドの「価値」という言葉を自分なりに再定義することで、アウトプット（成果物）ではなくアウトカム（効果）を意識する重要性を説いています。\n\n結論として、抽象的な言葉を自分自身の言葉に定義し直すことが、目標設定を単なる義務から価値を生み出すための仕組みへと変えるきっかけになると主張しています。エンジニアのキャリア形成や自己研鑽における思考の転換を促す内容です。","importance":6},{"title":"Anthropic、MCPサーバーがスキルを配信する「Skills over MCP」をパブリックベータ公開 ―Tasks、Elicitationの一般提供も開始 | gihyo.jp","url":"https://gihyo.jp/article/2026/11/skills-over-mcp","source":"Hatena","published_at":"2026-11-26 18:44","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AnthropicがMCPサーバーでスキル配信可能な新機能を提供","summary":"AnthropicはClaudeおよびClaude Code向けに、MCPサーバーが具体的な作業手順やプレイブックを配信できる「Skills over MCP」のパブリックベータを開始。これにより、AIエージェントはツールだけでなく、組織や個人に最適化された「スキルの進め方」を動的に読み込めるようになる。\n\n同時に、バックグラウンド処理を任せる「Tasks」や、処理中にユーザー確認を挟む「Elicitation」も一般提供を開始。MCPを単なるデータ接続プロトコルから、エージェント同士のオーケストレーション標準基盤へと進化させる方針を明確にしており、AIエージェント開発の転換点となるアップデートである。","importance":9},{"title":"集英社 販売サイト会員の生年月日など70万件余漏えい | NHKニュース","url":"https://news.web.nhk/newsweb/na/nd-20261126de82087","source":"Hatena","published_at":"2026-11-27 01:23","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"集英社、外部サービス「KARTE」への不正アクセスで70万件の個人情報漏えい","summary":"集英社は、キャラクターグッズ販売サイトの会員情報など約70万件が漏えいしたと発表した。原因は、メール配信やアプリの一部で使用していた外部サービス「KARTE」への不正アクセスである。\n\n漏えいした情報には生年月日などが含まれる。サプライチェーン攻撃の一種であり、自社だけでなく利用しているSaaSや外部サービスのセキュリティ管理が、企業全体の信頼性に直結するリスクを改めて浮き彫りにした。","importance":8},{"title":"WordPressのシェア低下をどう見るか——使っている人、静的HTMLやEmDashへ動く人の違い | WP Calm","url":"https://www.wpcalm.jp/topic/wordpress-market-share-decline-static-html-and-new-cms/","source":"Hatena","published_at":"2026-11-26 17:55","genre":"web","genre_label":"Web開発・言語","headline":"WordPressシェア低下の背景と運用現場における現実的な選択","summary":"WordPressのシェア低下が話題となる中、その内訳を分析し、単なる「WordPress離れ」ではなく、静的サイトや新しいCMSへの移行が進んでいる実態を解説しています。技術トレンドとしては静的HTMLやAI構築が注目されますが、企業サイトの運用現場では「管理画面からの修正容易性」や「保守体制の確保」といった理由から、依然としてWordPressが現実的な選択肢であると指摘しています。\n\n結論として、技術的な理想と現場の運用能力にはギャップがあり、チームで継続的に更新するメディア運営においては、安易な移行よりも運用体制に合わせたCMS選定が重要であると説いています。","importance":5},{"title":"AI使って開発するなら、モデリングするんだよ - 4つの図で始めるモデリングと、AIにモデルを実装させるアーキテクチャ","url":"https://speakerdeck.com/littlehands/umtp-suraido-20261125","source":"Hatena","published_at":"2026-11-27 08:54","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI時代こそモデリング！問題解決力を高める4つの図と実装手法","summary":"AIによる実装の高速化が進む中、エンジニアに求められる「問題解決力」をモデリングで強化する手法を解説。システム関連図、ユースケース図、オブジェクト図、ドメインモデル図の4つを活用し、不確実なプロダクト開発を乗り切るアプローチを提案しています。\n\nモデルを人とAIの共通言語として活用し、AIに実装を任せるためのアーキテクチャ設計の重要性を説いています。","importance":7},{"title":"Windows 11が「自動修復」ループで起動しない：BIOSで仮想化を無効にしたら起動した（NEC Mate 2台の記録）","url":"https://zenn.dev/yutakatsuhako/articles/9a7d7d1fde4cf7","source":"Zenn","published_at":"2026-11-26 19:54","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Windows 11自動修復ループをBIOS仮想化設定で解決","summary":"Windows 11の更新後に発生した「自動修復」ループ問題に対し、BIOS設定で仮想化（Intel VT）を無効にすることで起動を回復させた事例。Windows側で自動的に有効化された「仮想化ベースのセキュリティ（VBS）」と、特定のハードウェア環境との互換性問題が原因と推測される。\n\n高速スタートアップが有効な環境では、更新後の再起動まで問題が顕在化しないケースがあるため注意が必要。本記事は、イベントログの解析やレジストリ確認を通じた原因特定プロセスを詳細に記録しており、同様の起動トラブルに直面した際のトラブルシューティングとして極めて有用である。","importance":8},{"title":"「日本語で」と書いても AI が英語に戻るので、Stop フックで止めた","url":"https://zenn.dev/hitori_pm/articles/cc955887656339","source":"Zenn","published_at":"2026-11-26 22:22","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeの英語返答を防ぐStopフックによる言語制御","summary":"Claude Codeの指示ファイルで「日本語」を指定しても英語で返答される問題に対し、プログラムによる「Stopフック」を用いた自動制御を導入した事例。長い会話履歴やツール出力が英語である場合にAIが引きずられる現象を、返答内容を検査するPythonスクリプトで解決している。\n\n英字の割合や文の長さを判定基準にすることで、コードやURLなどの英語は許容しつつ、日本語の返答を強制する仕組みを構築。指示ファイルという「お願い」だけでなく、機械的にチェックする仕組みを導入することで、AI運用における再発防止策としての有効性を示している。","importance":8},{"title":"AWS セキュリティ成熟度モデル v3 と PCI DSS 版・AI 版の変更点と評価ツールを確認する","url":"https://zenn.dev/cscloud_blog/articles/new-aws-security-maturity-model","source":"Hatena","published_at":"2026-11-26 18:37","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWSセキュリティ成熟度モデルv3の変更点と評価ツール解説","summary":"AWSセキュリティ成熟度モデル（SMM）がv3へアップデートされ、クラウド版に加え「PCI DSS版」「AI版」の3エディション構成となった。評価ツールもExcelからWebアプリへ移行し、実装ガイダンスや検証方法が強化されている。\n\nv3ではAIやエージェント関連のコントロールが追加され、生成AIを開発に組み込む前提のセキュリティ対策が重視されている。監査チェックリストではなく、セキュリティ対策の優先順位付けやロードマップ策定のための指針として活用することで、組織のセキュリティ成熟度を効率的に向上させることが可能となる。","importance":8},{"title":"自動運転の予測軌跡の可視化動画を誰でも高速に作れるようにする","url":"https://zenn.dev/turing_motors/articles/cbf9872ca90166","source":"Zenn","published_at":"2026-11-26 17:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"自動運転の予測軌跡可視化をAWSで自動化・高速化する仕組み","summary":"自動運転モデルの予測軌跡を走行映像に重ねる動画生成プロセスを、AWS Step FunctionsとAWS Batchを用いて自動化した事例です。従来は手作業でGPU環境を準備する必要がありましたが、API経由でSlackに動画が届く仕組みを構築しました。\n\nボトルネックとなっていた学習用データセット作成の工程を見直し、並列処理や最適化を行うことで生成時間を大幅に短縮しています。コーディングエージェントを活用した最適化のプロセスも紹介されており、MLOpsにおける開発効率化の好例となっています。","importance":8},{"title":"自宅PCを格安ファイルサーバーとして構築してみた","url":"https://zenn.dev/nextbeat/articles/7c820845a91d7d","source":"Zenn","published_at":"2026-11-27 11:09","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Cloudflare TunnelとAuth0で構築する格安ファイルサーバー","summary":"ポート開放を行わずに外部からアクセス可能な自宅ファイルサーバーを構築した事例。Cloudflare Tunnelで経路を確保し、Auth0とCloudflare Accessを組み合わせて認証を実装しました。\n\nTerraformによるインフラ管理や、ソーシャルログインの活用により、セキュリティと利便性を両立。学習目的も兼ねて、ヘッダー認証を用いたユーザー紐づけなど、堅牢な構成を追求したエンジニアの取り組みです。","importance":6},{"title":"分離推論の KV 転送を push と pull で整理する","url":"https://zenn.dev/tosshi/articles/4e75a768f14852","source":"Zenn","published_at":"2026-11-27 03:29","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"分離推論におけるKVキャッシュ転送：push型とpull型の比較","summary":"LLMの分離推論（PrefillとDecodeを別インスタンスで実行）において、KVキャッシュの転送方式である「push」と「pull」を整理。vLLMが導入したpush型コネクタにより、TTFT（最初のトークンが出るまでの時間）が短縮された。\n\npull型はDecodeが読みに行く方式、push型はPrefillが書き込む方式である。push型は転送準備を生成プロセスから分離できるため効率的だが、システム構成や負荷状況に応じて最適な方式を選択する必要がある。","importance":7},{"title":"信頼ポリシーの設定ミスから始まる AWS アカウントの乗っ取り","url":"https://zenn.dev/akira1984/articles/6238528a4467ee","source":"Zenn","published_at":"2026-11-26 12:59","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"信頼ポリシーの設定ミスが招くAWSアカウント乗っ取りの脅威","summary":"GitHub ActionsとAWS間のOIDC信頼関係において、信頼ポリシーの設定ミス（広すぎる許可範囲）がAWSアカウントの乗っ取りにつながるリスクを解説しています。特にサブジェクト（sub）の条件設定が不適切な場合、攻撃者が悪意ある組織からロールを引き受けることが可能になります。\n\nTinder Security Labsの事例やMandiantのレポートを引用し、この脆弱性がCI/CDプロバイダー全般に共通するリスクであることを強調しています。セキュリティ競技会の問題作成を通じて、設定不備の発見と対策の重要性を啓蒙する内容です。","importance":9},{"title":"Adobe MAX で発表された MCP のうち、とりあえずIllustrator を測ってみた — 今はまだ JSX に届かない","url":"https://zenn.dev/pepe_3_go/articles/illustrator-three-routes-cost-measured","source":"Zenn","published_at":"2026-11-26 22:50","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Adobe MAX発表のMCP、Illustrator操作でJSXと比較検証","summary":"Adobe MAX 2026で発表されたIllustrator向けMCP（Model Context Protocol）を検証。従来のJSX（ExtendScript）と比較した結果、現時点ではJSXの方が効率的でコストも低いことが判明した。MCPは安全装置や読み取り機能に強みがあるものの、保存機能の欠如やツール定義の読み込みによるオーバーヘッドが課題である。\n\n今後は正式提供が進むにつれて改善が期待されるが、現段階ではJSXを完全に置き換えるには至っていない。特に数百か所の編集など大規模な作業では、往復回数やトークン消費が影響するため、用途に応じた使い分けが必要となる。","importance":7},{"title":"さくらインターネット、AWSやAzureなど他クラウドでバックアップ可能な新ストレージ「Object Storage Suite」（OS2）発表","url":"https://www.publickey1.jp/blog/26/awsazureobject_storage_suiteos2.html","source":"Hatena","published_at":"2026-11-27 02:19","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"さくらインターネット、マルチクラウド対応の新ストレージ「OS2」を発表","summary":"さくらインターネットが、AWSやAzureなど他クラウドへのバックアップを前提とした大容量ストレージサービス「Object Storage Suite」（OS2）を発表した。ペタバイトクラスの長期保存に適した設計となっている。\n\nデータのソブリンティ確保やランサムウェア対策として、マルチクラウドでのバックアップ需要に応える。料金体系はリクエスト数に依存しない従量課金外のモデルを検討しており、2027年中のリリースを予定している。","importance":7},{"title":"作業を止めずに進めるClaude Codeの/btw・/fork・/rewindなどの使い分け","url":"https://zenn.dev/nextbeat/articles/b0ccca979da06b","source":"Zenn","published_at":"2026-11-26 16:01","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeのコマンド使い分けによる開発効率化の極意","summary":"Claude Codeを用いた開発において、作業を止めずに質問や並列作業を行うためのコマンド（/btw, /fork, /rewindなど）の使い分けを解説しています。メインの会話を汚さずに軽い確認を行う/btwや、方針の分岐を試す/forkなど、状況に応じたコマンド選択が開発の継続性を高める鍵となります。\n\n特に、時間のかかる処理を裏で回す/backgroundや、git worktreeを活用した並列作業の重要性を強調しています。AIエージェントを開発のパートナーとして最大限活用するための実践的なコマンドリファレンスとして役立ちます。","importance":7},{"title":"迷惑メール対策をしているのに、なぜ詐欺メールは届くのか","url":"https://zenn.dev/akagumi/articles/catch-all-phishing-invisible-chars","source":"Zenn","published_at":"2026-11-26 23:08","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"迷惑メール対策をすり抜ける詐欺メールの巧妙な手口と対策","summary":"SPFやDMARCなどの認証を通過する詐欺メールの仕組みを解説。攻撃者は自前ドメインで認証をパスさせ、表示名やURLに制御文字（ゼロ幅文字やRLO）を混入させることで、キーワードフィルタを回避している。\n\n対策として、見えない文字のチェック、文字参照の段階的デコード、名乗っているブランドとリンク先ドメインの照合ロジックの強化が有効である。単純な認証だけでなく、コンテンツの構造を深く解析する防御策が求められている。","importance":7},{"title":"Snowflake AIMのデスクトップアプリでTeradataからの移行を検証してみた","url":"https://zenn.dev/snowflakejp/articles/snowflake-aim-app-teradata","source":"Zenn","published_at":"2026-11-26 13:07","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Snowflake AIMを用いたTeradataからのデータ基盤移行検証","summary":"Snowflake AIM for Data Warehousesアプリを活用し、TeradataからSnowflakeへのデータ基盤移行を検証したレポートです。コード変換からデータ検証までをGUIベースの対話型エージェント（AIM Agent）で進め、26オブジェクトの移行を短時間で完了させています。\n\nAIによる変換支援の有用性を確認しつつ、動的SQLやPERIOD型など一部の複雑な要素には手動修正が必要である点も指摘しています。大規模移行におけるAI活用と、その限界を理解するための実践的な検証記録です。","importance":7},{"title":"Zenoh のテンプレートを作った","url":"https://zenn.dev/rk_work/articles/zenoh-pico-ros2-guide","source":"Zenn","published_at":"2026-11-26 20:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Zenoh 1.10.2対応の通信ミドルウェア学習用テンプレート公開","summary":"ROS 2の代替としても注目される通信ミドルウェア「Zenoh」の最新版（1.10.2）を試せる学習用テンプレートを公開。APIが大きく変更された1.0系以降の情報不足を補うため、Python、Rust、C（zenoh-pico）、ROS 2間でのpub/subや問い合わせ、REST API連携までを網羅している。\n\nDocker環境でルーターを構築し、ESP32やPC間でデータをやり取りする構成をコマンドベースで解説。Zenohの柔軟なpub/subとストレージ機能を活用したデバッグ手法も紹介しており、次世代の通信ミドルウェアを導入したいエンジニアにとって即戦力となる構成となっている。","importance":7},{"title":"TenkaCloudSimulator 開発日記：ChatGPTのDotで開発が自律的に続く仕組みをつくる","url":"https://zenn.dev/bull/articles/tenkacloud-simulator-devlog-20261126","source":"Zenn","published_at":"2026-11-26 12:59","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ChatGPTのDotを活用した自律的な開発サイクルの構築","summary":"TenkaCloudSimulatorの開発において、ChatGPTのDotとサブエージェントを組み合わせ、Issueの起票から実装、レビュー、マージまでを自律的に回す仕組みを構築した記録です。トークン枠を気にせず試せる環境を整え、AGENTS.mdに完了条件をYAML形式で定義することで、AI同士の効率的な連携を実現しています。\n\nブラウザ内でのシミュレーター実行など、参加者がクラウド環境を用意せずに練習できる環境を目指しています。AIエージェントを開発チームの一員として機能させるための、実践的な運用ノウハウが詰まっています。","importance":8},{"title":"「安全な経路」の判定から学ぶ、Unix ソケット経由の Cloud SQL 認証エラー","url":"https://zenn.dev/rescuenow/articles/0e7f5fc4e46be3","source":"Zenn","published_at":"2026-11-26 14:08","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Unixソケット経由のCloud SQL認証エラーと安全な経路の判定","summary":"MySQLの認証プラグイン移行に伴い、Cloud RunのUnixソケット接続で認証エラーが発生した事例を基に、Unixソケット・TCP・TLSの接続方式の違いを解説しています。MySQLはUnixソケットを「安全な経路」とみなしますが、Auth Proxyの仕様により特定の環境で認証に失敗するケースがあることを明らかにしました。\n\n解決策として、Unixソケットの使用を避け、TCP接続や言語コネクタへの移行を推奨しています。DB接続の基礎知識を再確認し、クラウド環境における認証の仕組みを深く理解するための技術解説として非常に有益です。","importance":7}]};
